import{_ as a,o as r,a as i,b as m}from"./app.C41L12d5.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"高级AI Core编程模型","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/advanced_ai_core_programming_model"},{"text":"SIMD与SIMT混合编程","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/overview"},{"text":"概述","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/overview"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/overview.md","filePath":"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/overview.md","outlineHeaders":[{"level":2,"title":"混合编程的定位","slug":"混合编程的定位","link":"#混合编程的定位"},{"level":2,"title":"混合编程的适用场景","slug":"混合编程的适用场景","link":"#混合编程的适用场景"},{"level":2,"title":"指南概览","slug":"指南概览","link":"#指南概览"}],"lastUpdated":1788514879000}'),_={name:"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/overview.md"};function d(n,e,t,o,g,l){return r(),i("div",null,[...e[0]||(e[0]=[m('<div><article class="markdown-body"><h1>概述<span id="ZH-CN_TOPIC_0000002563469514"></span></h1><p>为提升向量计算在复杂控制流、离散访存等场景下的编程灵活性，在SIMD与SIMT深度融合的混合编程架构中：矩阵计算单元延续SIMD设计，向量计算单元则在SIMD基础上引入SIMT能力。这一设计确立了以SIMD为主、SIMT为辅的混合编程模型。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 该编程模型适用于如下型号： <span data-filter="950"></span></p><ul><li>Ascend 950PR/Ascend 950DT </li></ul></div><h2 id="混合编程的定位">混合编程的定位<a class="header-anchor" href="#混合编程的定位">​</a></h2><p>在该模型下，矩阵计算单元和向量计算中的SIMD计算单元共同提供超过90%的算力，为密集计算提供高性能与高算力利用率；向量计算中的SIMT则作为灵活性补充，专门应对复杂控制流、离散访存等不规则场景，提升此类场景下算法开发与优化的效率。<br> 因此，在SIMD与SIMT混合编程中，SIMT不用于替代SIMD处理连续、密集的计算任务，而是用于处理算子中的局部不规则逻辑。典型方式是在核函数（Kernel）中通过SIMT VF处理分支判断、索引映射、离散访存等局部片段，再由SIMD继续处理向量或矩阵计算，从而兼顾灵活性和高吞吐。</p><h2 id="混合编程的适用场景">混合编程的适用场景<a class="header-anchor" href="#混合编程的适用场景">​</a></h2><p>如上文所述，混合编程适用于算子功能既包含SIMD擅长的连续规整计算，也包含SIMT擅长的离散访问等任务的场景。以下列举部分混合编程的适用场景：</p><ul><li><p>复杂分支判断的算子，适合使用SIMT完成计算任务，而输入输出的数据搬运较规整连续，适合使用SIMD搬运接口完成数据拷贝。例如<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/05_simd_simt_hybrid/02_best_practices/simd_simt_high_performance">floor_mod样例</a>。</p></li><li><p>离散访问场景，适合使用SIMT完成计算任务，当所需访问的数据量远小于Unified Buffer（UB）可用空间时，可以使用SIMD搬运接口完成数据拷贝，使SIMT编程能够直接从UB读取数据，提高内存访问效率。</p></li><li><p>某些算子，在大Shape场景，使用SIMD并行计算效率更高；而在小Shape不规整场景，则适合使用SIMT完成计算。因此可以区分算子场景，分别使用两种编程方式实现算子功能，提升泛化场景整体性能。</p></li></ul><h2 id="指南概览">指南概览<a class="header-anchor" href="#指南概览">​</a></h2><p>混合编程作为高级编程方式，在阅读本章节内容前需对<a href="../../../programming_model/ai_core_simd_programming/ai_core_simd_programming.html">SIMD编程模型</a>和<a href="../../../programming_model/ai_core_simt_programming/ai_core_simt_programming.html">SIMT编程模型</a>有一定的了解。本章节将从以下几个方面展开介绍混合编程：</p><ul><li><p><strong><a href="abstract_hardware_architecture.html">抽象硬件架构</a></strong>：介绍了SIMD与SIMT混合编程场景的硬件架构，介绍VF（Vector Function）运行机制及SIMT VF、SIMD VF等概念。</p></li><li><p><strong><a href="kernel_and_vf_functions.html">核函数（Kernel）与VF函数</a></strong>：详细介绍了混合编程场景的核函数（Kernel）定义、调用方式及执行配置，VF函数及各类函数的调用关系。</p></li><li><p><strong><a href="memory_hierarchy.html">内存层级</a></strong>：展示混合编程场景的内存层级，重点介绍了VF之间的通信方式，UB内存作为共享内存是如何分配与管理的。</p></li><li><p><strong><a href="programming_examples.html">编程示例</a></strong>：以实际样例展示混合编程关键语法，包括<code>asc_vf_call</code>调用SIMT VF函数和<code>&lt;&lt;&lt;&gt;&gt;&gt;</code>核函数（Kernel）启动配置。</p></li></ul><p>强烈建议开发者阅读<a href="../../../language_extension/simd_simt_hybrid_builtin_keywords.html">混合编程场景的扩展语法与约束说明</a>，掌握基本扩展语法及使用约束后开发自定义算子。</p></article></div>',1)])])}const c=a(_,[["render",d]]);export{p as __pageData,c as default};
